import{_ as a,o as i,c as t,a2 as o}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"Sovereign OS Roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"sovereign-os/roadmap.md","filePath":"sovereign-os/roadmap.md"}'),r={name:"sovereign-os/roadmap.md"};function n(s,e,l,d,c,p){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="sovereign-os-roadmap" tabindex="-1">Sovereign OS Roadmap <a class="header-anchor" href="#sovereign-os-roadmap" aria-label="Permalink to &quot;Sovereign OS Roadmap&quot;">​</a></h1><h2 id="status-legend" tabindex="-1">Status Legend <a class="header-anchor" href="#status-legend" aria-label="Permalink to &quot;Status Legend&quot;">​</a></h2><ul><li>✅ Complete — implemented and qualified on supported hardware</li><li>🟡 In progress — implementation or hardware qualification is active</li><li>⚪ Planned — accepted direction, not yet started</li><li>⏳ Pending decision — research or an RFC must close the design boundary</li></ul><h2 id="current-position" tabindex="-1">Current Position <a class="header-anchor" href="#current-position" aria-label="Permalink to &quot;Current Position&quot;">​</a></h2><p>✅ Phase 01 — Flashable Raspberry Pi Image POC</p><p>The Raspberry Pi 5 image build, flash, first-boot, Pi-hole, persistent DATA partition, local routing, first-login, and Sovereign Console health experience have been exercised on physical hardware.</p><p>🟡 Milestone 01.1 — Appliance Update Foundation</p><p>The signed appliance updater can inspect, prepare, back up, stage, activate, health-check, commit, recover, and roll back versioned releases while preserving the dedicated DATA partition. An initial signed update transaction passed Raspberry Pi qualification.</p><p>The first fully versioned appliance-release qualification, from preview.9 to preview.10, exposed service-readiness and systemd dependency races. Automatic rollback worked and restored preview.9. The fixes were qualified on Raspberry Pi 5 hardware in a clean preview.11 base to preview.12 update campaign: an interrupted-at-<code>validating</code> recovery, a forced target-health rollback, and a successful activation all held with reboot persistence and no regression to Console, DNS, Pi-hole, Nginx, SSH, credentials, or the dedicated DATA partition. See the <a href="./docs/research/preview-12-appliance-update-qualification-report.html">preview.12 appliance update qualification report</a>.</p><p>Persistent-data restore, bounded retention (<code>prune</code>), and signed trust rotation (<code>rotate-trust</code>) are all implemented and hardware-qualified on Raspberry Pi 5, most recently against a real <code>0.1.0-preview.13</code> base image built and flashed with all three shipped in for the first time — see the <a href="./docs/research/preview-14-appliance-update-qualification-report.html">preview.14 appliance update qualification report</a> and the <a href="./docs/research/prune-and-rotate-trust-hardware-qualification-report.html">prune and trust rotation hardware qualification report</a>. Production signing-key custody is decided (ADR-0006), and the production key (<code>sovereign-production-1</code>) is now generated, provisioned into the image-builder trust store, and proven end-to-end: <code>v0.1.0-preview.17</code> is a real production-signed release that has been built, published, discovered, installed, and restored from on Raspberry Pi 5 hardware — see the <a href="./docs/research/first-production-signed-release-qualification-report.html">first production-signed release</a>, <a href="./docs/research/first-production-signed-release-install-qualification-report.html">install</a>, and <a href="./docs/research/production-signed-restore-qualification-report.html">restore</a> qualification reports. <code>prune</code> and <code>rotate-trust</code> have not yet been exercised as part of a real signed-release install cycle.</p><p>Unattended automatic installation remains disabled until the manual, health-gated update path and its operational controls are qualified.</p><h2 id="milestone-sequence" tabindex="-1">Milestone Sequence <a class="header-anchor" href="#milestone-sequence" aria-label="Permalink to &quot;Milestone Sequence&quot;">​</a></h2><h3 id="_1-complete-appliance-update-qualification" tabindex="-1">1. Complete Appliance Update Qualification <a class="header-anchor" href="#_1-complete-appliance-update-qualification" aria-label="Permalink to &quot;1. Complete Appliance Update Qualification&quot;">​</a></h3><p><strong>Status:</strong> ✅ Complete</p><p><strong>User outcome:</strong> Install a compatible Sovereign appliance release without reflashing or losing persistent data.</p><p>Qualification pair:</p><ul><li>preview.11: clean flashable base containing the systemd and readiness fixes;</li><li>preview.12: signed, versioned installed-device update built from the same source revision.</li></ul><p>The physical qualification on Raspberry Pi 5 proved:</p><ul><li>update compatibility and signature verification;</li><li>staging without changing the active release;</li><li>interruption recovery (interrupted at <code>validating</code>, automatic boot-time restore of preview.11);</li><li>forced health-check failure and automatic rollback;</li><li>successful activation and commit;</li><li>reboot persistence;</li><li>preservation of Pi-hole configuration, credentials, update state, and the dedicated DATA mount; and</li><li>no regression to Console, DNS, Pi-hole, Nginx, or SSH.</li></ul><p>See the <a href="./docs/research/preview-12-appliance-update-qualification-report.html">preview.12 appliance update qualification report</a> for full evidence.</p><h3 id="_2-production-update-operations" tabindex="-1">2. Production Update Operations <a class="header-anchor" href="#_2-production-update-operations" aria-label="Permalink to &quot;2. Production Update Operations&quot;">​</a></h3><p><strong>Status:</strong> 🟡 In progress</p><p><strong>Depends on:</strong> Completed preview.11 to preview.12 qualification</p><p><strong>User outcome:</strong> A supportable update mechanism with trustworthy release and recovery operations.</p><p>Planned work:</p><ul><li>automate persistent-data restore verification — <code>sovereign-update restore</code> is implemented and hardware-qualified against real Pi-hole state on Raspberry Pi 5, including a forced-health-failure rollback path, twice now: once manually deployed, and again on a real <code>preview.13</code> base image that shipped it natively (see <a href="./update/BACKUP_AND_JOURNAL.html">BACKUP_AND_JOURNAL.md</a> and the <a href="./docs/research/restore-hardware-qualification-report.html">restore</a> and <a href="./docs/research/preview-14-appliance-update-qualification-report.html">preview.14</a> qualification reports); it still has not shipped through a release used by anyone beyond qualification, and is not yet wired into automatic update rollback for future data migrations;</li><li>define bounded retention and cleanup for old releases, backups, journals, and failed transactions — <code>sovereign-update prune [--dry-run]</code> is implemented and hardware-qualified on Raspberry Pi 5 against real backups, releases, and transaction journals, including confirming the live device stays healthy through an aggressive real deletion pass (see <a href="./update/BACKUP_AND_JOURNAL.html">BACKUP_AND_JOURNAL.md</a> and the <a href="./docs/research/prune-and-rotate-trust-hardware-qualification-report.html">prune and trust rotation qualification report</a>). Now wired into a daily <code>sovereign-update-prune.timer</code> (jittered, catches up on boot if a run was missed), hardware-verified running under its own hardened sandbox on Raspberry Pi 5; not yet shipped through a release beyond qualification, and an actual unattended timer-elapsed run has not been separately observed;</li><li>establish production signing-key custody, rotation, and revocation — decided in <a href="./docs/adrs/0006-production-signing-key-custody.html">ADR-0006</a> (password-manager-held key, hardware key as a future upgrade). Routine rotation/revocation is implemented as <code>sovereign-update rotate-trust</code> (signed, atomic, refuses any change that would leave a channel with no trusted key — see <a href="./update/README.html">update/README.md</a>&#39;s &quot;Trust Rotation v1&quot; section) and hardware-qualified on Raspberry Pi 5, including the realistic single-key rotation handoff, immediate enforcement of revocation, and the lockout protection (see the <a href="./docs/research/prune-and-rotate-trust-hardware-qualification-report.html">prune and trust rotation qualification report</a>). The production key (<code>sovereign-production-1</code>, Ed25519, scoped to both <code>preview</code> and <code>stable</code>) has now been generated under that custody decision and its public half is baked into the image-builder overlay&#39;s trust store, so future base images trust it out of the box; the private half lives only as an encrypted secret in the maintainer&#39;s password manager. <code>v0.1.0-preview.17</code> is the first release signed with it, published, discovered, and — as of a full <code>prepare</code>/<code>backup</code>/<code>stage</code>/ <code>activate</code> run on the same Raspberry Pi 5 — genuinely <strong>installed</strong>: the device now runs <code>0.1.0-preview.17</code>, <code>update_state: committed</code>, confirmed across a cold reboot. See the <a href="./docs/research/first-production-signed-release-qualification-report.html">discovery</a> and <a href="./docs/research/first-production-signed-release-install-qualification-report.html">install</a> qualification reports. That install campaign also found and fixed a real regression: <code>sovereign-proof.service</code> failing on any boot after <code>prune</code> removes the base image&#39;s own (now-inactive) release directory — <code>proof-init</code> now only performs that check during first-boot bootstrap. <code>restore</code> has since also been qualified against the real pre-activation backup that install created: correctly rejected a version-mismatched restore by default, then recovered an injected canary correctly under <code>--force</code> with no regression — see the <a href="./docs/research/production-signed-restore-qualification-report.html">production-signed restore qualification report</a>. <code>prune</code>/<code>rotate-trust</code> still haven&#39;t been exercised as part of an actual signed-release install cycle — doing so meaningfully needs either a second real release or a genuine key rotation, not a manufactured scenario. Getting a rotation manifest onto already-flashed devices without an operator manually running the command still depends on the Update Discovery work in item 3 below;</li><li>approve the update RFC and production manifest policy;</li><li>publish release compatibility, rollback limitations, and recovery guidance — published as <a href="./docs/operations/update-recovery-and-compatibility.html">docs/operations/update-recovery-and-compatibility.md</a>, written for the device operator rather than a contributor; and</li><li>qualify every supported source-to-target update path on real hardware. A <code>0.1.0-preview.17</code> → <code>0.1.0-preview.18</code> attempt surfaced a real structural gap: the installed updater&#39;s appliance file allowlist was fixed at flash time and couldn&#39;t learn about a new file added by the release introducing it. Fixed and hardware-qualified the same day — the validator now rejects only missing required files, not unrecognized ones, and classifies appliance scripts by shebang instead of a hardcoded name set; the exact real stuck transaction was recovered through to <code>committed</code> on real hardware, confirmed persistent across a reboot — see <a href="./docs/research/appliance-file-set-update-ceiling-finding.html">the finding</a> and its <a href="./docs/research/appliance-file-set-ceiling-fix-qualification-report.html">fix qualification report</a>. This does not touch the larger, still-unresolved question of delivering new systemd units/base-image content via update at all (see item 6 below) — only the narrower file-allowlist symptom.</li></ul><h3 id="_3-update-discovery-and-console-controls" tabindex="-1">3. Update Discovery and Console Controls <a class="header-anchor" href="#_3-update-discovery-and-console-controls" aria-label="Permalink to &quot;3. Update Discovery and Console Controls&quot;">​</a></h3><p><strong>Status:</strong> 🟡 In progress</p><p><strong>Depends on:</strong> Production Update Operations for the Console-facing and installation-triggering bullets below; the device-side check-and-notify bullet was deliberately scoped in RFC-0015 to not depend on it (no Console change, no production key) and has already started.</p><p><strong>User outcome:</strong> Learn about and install <code>x+1</code> from Sovereign Console without using the command line or reflashing.</p><p>Planned work:</p><ul><li>publish signed update-channel metadata over HTTPS, and periodically check for compatible updates without sending household data — accepted in <a href="./docs/rfcs/0015-update-discovery.html">RFC-0015</a> and implemented as <code>sovereign-update check</code>, reusing the existing signed-manifest verification unchanged, with no new trust logic, no Console change, and no production key required. Runs daily via <code>sovereign-update-check.timer</code>, hardware-verified on Raspberry Pi 5 against the real live GitHub API, including the positive &quot;update found&quot; path against a genuinely published (non-draft) release — see <a href="./update/README.html">update/README.md</a>&#39;s &quot;Update Discovery v1&quot; section and the <a href="./docs/research/update-discovery-positive-path-qualification-report.html">positive-path qualification report</a>. That campaign also surfaced a real gap, now fixed: <code>build-image.yml</code>&#39;s release-publish step never uploaded the update-candidate manifest/bundle at all, and its filename collided with the image&#39;s own provenance file (now <code>image-manifest.json</code>). The workflow now conditionally uploads the unsigned update-candidate assets when <code>build_update_candidate</code> is selected; an operator still has to sign and upload the <code>.sig</code> offline before a release becomes discoverable;</li><li><strong>Console authentication</strong> — the prerequisite ADR-0005 itself named before any mutating Console action can exist. Decided and implemented in <a href="./docs/adrs/0007-console-authentication.html">ADR-0007</a>: a separate Console-specific credential (<code>sovereign-console-password</code>), a loopback-only, systemd-hardened login backend (<code>sovereign-console-auth</code>, <code>/api/v1/auth/*</code>), session cookies with CSRF protection, and per-source rate limiting without lockout, with a sign-in UI wired into Console&#39;s topbar. Unit-tested (<code>tests/test_console_auth.py</code>) and hardware-qualified on Raspberry Pi 5 — see the <a href="./docs/research/console-authentication-hardware-qualification-report.html">console authentication hardware qualification report</a>. A real signed-release install attempt (<code>v0.1.0-preview.18</code>) surfaced a structural finding bigger than Console auth itself — see <a href="./docs/research/appliance-file-set-update-ceiling-finding.html">the finding</a> — since fixed: <code>.18</code> is genuinely installed via a real update on real hardware, <code>console-auth</code>&#39;s binary included. The base-image content it also needs (systemd unit, <code>sysusers.d</code> group, directory bootstrap) was then deployed manually and permanently to the qualification device — real, accepted drift against what any future image build produces until the next reflash, not something an update can deliver (tracked at item 6 below). Console authentication is now genuinely live and working on real hardware;</li><li><strong>the first Console-triggered privileged action</strong> — decided and implemented in <a href="./docs/adrs/0008-console-privileged-action-invocation.html">ADR-0008</a>: a file-existence trigger picked up by a <code>systemd</code> path-activated, root-owned oneshot runner, scoped to exactly one action, <code>sovereign-update check</code>. Hardware-qualified on Raspberry Pi 5 — the full chain (auth/CSRF gating, the trigger actually firing, a real check running as root, the result surfacing back to Console, cooldown enforcement) verified correctly, after finding and fixing two real defects (a missing <code>ReadWritePaths=</code> grant, and a static-group name that collided with an unrelated service&#39;s own <code>DynamicUser</code> identity) — see the <a href="./docs/research/console-check-trigger-hardware-qualification-report.html">qualification report</a>. <code>prepare</code>/<code>backup</code>/<code>stage</code>/<code>activate</code> (an actual install trigger) are explicitly out of scope for this pass — deliberately smaller blast radius first;</li><li>show version, channel, release notes, download size, reboot requirements, and rollback limitations in Console;</li><li>provide user-triggered download and installation;</li><li>report download, verification, staging, activation, validation, rollback, and completion states; and</li><li>retain a CLI recovery path independent of Console.</li></ul><p>The initial policy is <strong>notify and require approval</strong>. Automatic download and maintenance-window installation follow only after repeated field qualification. Every automatic policy retains signature verification, health-gated activation, and automatic rollback.</p><h3 id="_4-local-conversation-and-capabilities" tabindex="-1">4. Local Conversation and Capabilities <a class="header-anchor" href="#_4-local-conversation-and-capabilities" aria-label="Permalink to &quot;4. Local Conversation and Capabilities&quot;">​</a></h3><p><strong>Status:</strong> ⚪ Planned; research and RFC work may proceed in parallel</p><p><strong>Depends on:</strong> Stable appliance update boundary</p><p><strong>User outcome:</strong> Ask Sovereign local questions, inspect system and Pi-hole status, and explicitly use privacy-transparent, self-hosted web-search tooling.</p><p>Milestone 01.2 will deliver:</p><ul><li>a Sovereign-owned conversation experience;</li><li>provider-neutral local inference and model-management contracts;</li><li>a Raspberry Pi 5 benchmark of llama.cpp and Ollama;</li><li>a typed capability registry and deterministic executor;</li><li><code>system.health</code> and read-only Pi-hole capabilities;</li><li>opt-in <code>web.search</code> through a locally operated SearXNG instance;</li><li>restricted <code>web.fetch</code>, citations, privacy indicators, and audit events; and</li><li>real-hardware qualification within DNS-latency, memory, power, and thermal budgets.</li></ul><h3 id="_5-home-automation-integration" tabindex="-1">5. Home Automation Integration <a class="header-anchor" href="#_5-home-automation-integration" aria-label="Permalink to &quot;5. Home Automation Integration&quot;">​</a></h3><p><strong>Status:</strong> ⚪ Planned</p><p><strong>Depends on:</strong> Qualified capability executor</p><p><strong>User outcome:</strong> Ask about and safely control allowlisted home entities through the same Sovereign conversation boundary.</p><p>The first slice is read-only Home Assistant entity discovery, state, and history. Later slices may propose allowlisted actions, but deterministic policy outside the model must authorize them and require confirmation according to risk. The model never receives unrestricted Home Assistant, shell, Docker, or network access.</p><h3 id="_6-full-base-os-updates" tabindex="-1">6. Full Base-OS Updates <a class="header-anchor" href="#_6-full-base-os-updates" aria-label="Permalink to &quot;6. Full Base-OS Updates&quot;">​</a></h3><p><strong>Status:</strong> ⏳ Architecture decision pending</p><p><strong>Depends on:</strong> Stable appliance updater and persistent partition contract</p><p><strong>User outcome:</strong> Update Debian, kernel, firmware, Docker, and early system services without reflashing.</p><p>The current updater covers versioned Sovereign appliance releases; it does not make base-OS package transactions atomic. The long-term milestone must select and qualify an A/B root-filesystem or equivalent immutable deployment design with:</p><ul><li>persistent DATA independent of either system slot;</li><li>atomic boot-slot selection;</li><li>boot and health confirmation;</li><li>automatic fallback to the previous system;</li><li>signed system artifacts; and</li><li>an external recovery-image path.</li></ul><p>This milestone closes the remaining “flash once” gap.</p><h2 id="progress-summary" tabindex="-1">Progress Summary <a class="header-anchor" href="#progress-summary" aria-label="Permalink to &quot;Progress Summary&quot;">​</a></h2><ul><li>✅ Concept paper and master plan</li><li>✅ Phase 01 appliance architecture decision</li><li>✅ <code>rpi-image-gen</code> assessment, proof build, and automated ARM64 image pipeline</li><li>✅ Flashable Raspberry Pi 5 image exercised on hardware</li><li>✅ Docker-based Pi-hole, <code>/dns/*</code> routing, and persistent DATA</li><li>✅ First-login credential-change and optional SSH-key flow</li><li>✅ Sovereign Console read-only health page qualified on Raspberry Pi 5</li><li>✅ Signed update transaction, interruption recovery, rollback, and persistence demonstrated on Raspberry Pi 5</li><li>✅ Fully versioned appliance-release qualification (preview.11 to preview.12), including readiness hardening</li><li>🟡 Persistent restore automation, retention, and production signing operations</li><li>🟡 Update discovery and Sovereign Console update controls</li><li>⏳ Local inference benchmark and conversation/capability RFCs</li><li>⚪ SearXNG-backed web-search capability</li><li>⚪ Home Assistant capability integration</li><li>⏳ A/B or equivalent full base-OS update architecture</li></ul><hr><h2 id="phases" tabindex="-1">Phases <a class="header-anchor" href="#phases" aria-label="Permalink to &quot;Phases&quot;">​</a></h2><ul><li><a href="./docs/roadmap/00-master-plan.html">00 Master Plan</a></li><li><a href="./docs/roadmap/01-preview-poc.html">01 Flashable Pi-hole Image POC</a></li><li><a href="./docs/roadmap/01-console-foundation.html">Console Foundation</a></li><li><a href="./docs/roadmap/01-1-update-foundation.html">01.1 Appliance Update Foundation</a></li><li><a href="./docs/roadmap/01-2-local-conversation-capabilities.html">01.2 Local Conversation and Capabilities</a></li></ul><h2 id="project-documentation" tabindex="-1">Project Documentation <a class="header-anchor" href="#project-documentation" aria-label="Permalink to &quot;Project Documentation&quot;">​</a></h2><ul><li><a href="./docs/README.html">Documentation index</a></li><li><a href="./docs/product/target-user.html">Initial target user</a></li><li><a href="./docs/product/core-use-cases.html">Core preview use cases</a></li><li><a href="./docs/product/preview-scope.html">Preview scope and non-goals</a></li><li><a href="./docs/architecture/system-overview.html">System overview</a></li><li><a href="./docs/security/threat-model.html">Preview threat model</a></li><li><a href="./docs/adrs/0001-phase-01-appliance-architecture.html">ADR-0001: Phase 01 appliance architecture</a></li><li><a href="./docs/rfcs/0010-raspberry-pi-image-deployment.html">RFC-0010: Raspberry Pi image deployment</a></li><li><a href="./docs/operations/image-release-checklist.html">Image release checklist</a></li><li><a href="./docs/adrs/0002-install-images-and-update-artifacts.html">ADR-0002: Installation images and update artifacts</a></li><li><a href="./docs/adrs/0004-provider-neutral-assistant-and-web-search.html">ADR-0004: Provider-neutral assistant and web search</a></li><li><a href="./docs/adrs/0005-sovereign-console-and-health-boundary.html">ADR-0005: Sovereign Console namespace and health boundary</a></li><li><a href="./docs/rfcs/0014-appliance-update-system.html">RFC-0014: Appliance update system</a></li><li><a href="./docs/research/preview-12-appliance-update-qualification-report.html">Preview.12 appliance update qualification report</a></li></ul>',58)])])}const m=a(r,[["render",n]]);export{h as __pageData,m as default};
